import { CommunityStatus } from '../modules/community/entities/community.entity'
import { PropertyStatus, PropertyType } from '../modules/property/entities/property.entity'
import { OccupancyStatus, UnitStatus, UnitType } from '../modules/unit/entities/unit.entity'

// Community / Property / Unit master data loaded once, on a fresh database, by BootstrapService.seedLocations.
//
// Sourced verbatim from seed-community-property-unit.sql (itself taken from the CCB_Template dataset) — nothing here is
// invented or randomised. seed-units-random.sql is deliberately NOT part of the first-time initialization: random
// units are not reference data.
//
// Differences from that SQL file, on purpose:
//  - the units' `master_meter_id` / `sub_meter_id` values are dropped: the units table has no such columns (meters
//    live in master_meters / sub_meters and link to a unit from there), so the SQL no longer ran against the schema;
//  - properties and units reference their parent by business key (community `code`, property `code`) — resolved to
//    ids at seed time, exactly as the SQL's sub-selects did;
//  - `business_code` (COM-/PRP-/UNT-000001 …) is generated by the seed from the new row id, the same rule as
//    generateBusinessCode, instead of the SQL's trailing UPDATE.
// The template defines units only for the first five Azizi Rivera towers (AZR-T01 … AZR-T05); the other 62 properties
// intentionally have none.

export interface SeedCommunity {
  code: string
  name: string
  status: CommunityStatus
  description: string
  location: string
  address: string
  city: string
  state: string
  zipCode: string
  country: string
  contactPerson: string
  contactEmail: string
  contactPhone: string
}

export interface SeedProperty {
  communityCode: string
  code: string
  name: string
  propertyType: PropertyType
  numberOfFloors: number
  status: PropertyStatus
}

export interface SeedUnit {
  propertyCode: string
  unitNumber: string
  floorNumber: number
  unitType: UnitType
  unitSize: number
  occupancyStatus: OccupancyStatus
  status: UnitStatus
  bedrooms: number | null
  bathrooms: number | null
  balcony: boolean
  parkingSpaces: number
  monthlyRent: number
  handoverDate: string
  ownerId: string | null
  tenantId: string | null
  amenities: string[]
  description: string
}

